package com.adrianausin.wallet.adapter.out.persistence;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

@Entity
@Table(name = "ledger_entries")
class LedgerEntryEntity {

    @Id
    private UUID id;

    /** Generated by the database (identity column), never written by the application. */
    @Column(insertable = false, updatable = false)
    private Long seq;

    @Column(name = "wallet_id", nullable = false)
    private UUID walletId;

    @Column(name = "transaction_id", nullable = false)
    private UUID transactionId;

    @Column(nullable = false)
    private String type;

    @Column(nullable = false, precision = 19, scale = 4)
    private BigDecimal amount;

    @Column(nullable = false, length = 3)
    private String currency;

    @Column(name = "balance_after", nullable = false, precision = 19, scale = 4)
    private BigDecimal balanceAfter;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    protected LedgerEntryEntity() {
    }

    LedgerEntryEntity(UUID id, UUID walletId, UUID transactionId, String type, BigDecimal amount,
                      String currency, BigDecimal balanceAfter, Instant createdAt) {
        this.id = id;
        this.walletId = walletId;
        this.transactionId = transactionId;
        this.type = type;
        this.amount = amount;
        this.currency = currency;
        this.balanceAfter = balanceAfter;
        this.createdAt = createdAt;
    }

    UUID getId() {
        return id;
    }

    UUID getWalletId() {
        return walletId;
    }

    UUID getTransactionId() {
        return transactionId;
    }

    String getType() {
        return type;
    }

    BigDecimal getAmount() {
        return amount;
    }

    String getCurrency() {
        return currency;
    }

    BigDecimal getBalanceAfter() {
        return balanceAfter;
    }

    Instant getCreatedAt() {
        return createdAt;
    }
}
